{
  "packet_id": "H6-T02-1",
  "claim_id": "C030",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C030",
    "value": "Preselecting replication and repeated-testing rules is proposed to prevent uncontrolled error accumulation across repeated midpoint decisions.",
    "scope": "Rationale for prospective testing rules; no particular rule or error bound is specified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P018 explicitly supplies both the proposed advance selection and its error-control purpose."
    }
  },
  "signal_basis": {
    "component_id": "C030_signal_basis",
    "value": "Repeated midpoint decisions use uncertain estimates of tail frequency to classify revisions; replication and repeated-testing rules are to be chosen prospectively.",
    "scope": "The repeated statistical classification procedure, without an observed or quantified overall error rate.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish midpoint decisions, uncertainty-based classifications, and prospective selection of testing rules."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C030_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No conditional empirical warrant is required for this bounded design rationale."
    }
  },
  "rationale": "Repeated statistical decisions motivate planning replication and error handling in advance. This licenses the stated proposal and its purpose. The claim does not assert that advance selection alone guarantees error control or that a particular bound has been achieved.",
  "uncertainty": "Whether the eventual testing rule actually controls accumulated error remains unspecified; this limits efficacy conclusions, not the stated rationale.",
  "anomalies": []
}
